(async()=>{'use strict';const section=document.createElement('section');section.id='course-bundles';section.style.cssText='margin:24px 0;padding:20px;border:1px solid #52766c;border-radius:20px;background:#082320;color:white';section.innerHTML='<h2>Choose your next courses</h2><p>Choose any 2 for ₦40,000 or any 4 for ₦75,000. Courses you own stay yours. The ebook is sold separately.</p><p role="status">Loading your course options…</p>';const anchor=document.querySelector('.academy-cards');(anchor?.parentElement||document.querySelector('main')).append(section);let count=2,busy=false;const selected=new Set();try{const sb=await Fuse.client();const {data:{session}}=await sb.auth.getSession();const r=await fetch('/api/academy-catalog',{headers:session?{authorization:'Bearer '+session.access_token}:{},cache:'no-store'});if(!r.ok)throw Error('Could not load courses. Reload to try again.');const data=await r.json();section.innerHTML='<h2>Build your course bundle</h2><div><button type="button" data-count="2">Choose 2 · ₦40,000</button> <button type="button" data-count="4">Choose 4 · ₦75,000</button></div><p>Select courses you haven’t unlocked.</p><div data-options></div><p data-total></p><button type="button" data-buy>Continue to Paystack</button><p role="status"></p>';const options=section.querySelector('[data-options]'),status=section.querySelector('[role=status]'),buy=section.querySelector('[data-buy]');for(const c of data.courses){const label=document.createElement('label');label.style.cssText='display:block;padding:12px;border-bottom:1px solid #33534b';const input=document.createElement('input');input.type='checkbox';input.value=c.key;input.disabled=c.owned;label.append(input,document.createTextNode(' '+c.label+' · ₦'+c.amount_naira.toLocaleString('en-NG')+(c.owned?' · Already unlocked':'')));input.onchange=()=>{if(input.checked&&selected.size>=count){input.checked=false;return}input.checked?selected.add(c.key):selected.delete(c.key);render()};options.append(label)}function render(){const sum=data.courses.filter(c=>selected.has(c.key)).reduce((n,c)=>n+c.amount_naira,0);const total=Math.min(sum,count===2?40000:75000);section.querySelector('[data-total]').textContent=selected.size+'/'+count+' selected · Total ₦'+total.toLocaleString('en-NG')+(sum>total?' · Save ₦'+(sum-total).toLocaleString('en-NG'):'');buy.disabled=busy||selected.size!==count;section.querySelectorAll('[data-count]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.count===count)))}section.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{count=+b.dataset.count;selected.clear();options.querySelectorAll('input').forEach(i=>i.checked=false);render()});buy.onclick=async()=>{if(!data.signedIn){location.assign('/signup?next='+encodeURIComponent('/atelier-v2/learn.html#course-bundles'));return}busy=true;render();status.textContent='Preparing secure NGN checkout…';try{const out=await Fuse.api('paystack-init',{pack:'academy-bundle-'+count,courses:[...selected]});const url=new URL(out.authorization_url);if(url.protocol!=='https:'||url.hostname!=='checkout.paystack.com')throw Error('Invalid checkout URL');location.assign(url.href)}catch(e){status.textContent=e.message;busy=false;render()}};render()}catch(e){section.querySelector('[role=status]').textContent=e.message}})();
